package ultra.downloads;
import android.app.Activity;import java.util.*;import java.io.*;import java.lang.reflect.*;import java.util.concurrent.*;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33)
public class DL24PinPerformanceTest {
 @Test public void noWholeTransformMonitor()throws Exception{assertFalse(Modifier.isSynchronized(LibraryPinOrder.class.getMethod("reorder",byte[].class,android.content.Context.class).getModifiers()));}
 static byte[] row(String id){return HeaderCommands.field(5,HeaderCommands.field(0x2e6ea0a,HeaderCommands.field(2,HeaderCommands.text(id))));}
 @Test public void fourHundredRowsRemainIdentifiedAndReordered()throws Exception{Activity c=Robolectric.buildActivity(Activity.class).setup().get();ByteArrayOutputStream out=new ByteArrayOutputStream();for(int n=0;n<400;n++)out.write(HeaderCommands.field(7,row(n==399?"FEmusic_ultra_radio":"VLPLtest"+n)));byte[] input=out.toByteArray();long s=System.nanoTime();byte[] result=LibraryPinOrder.reorder(input,c);assertEquals("ULTRA_RADIO",LibraryPinOrder.rowKey(HeaderCommands.fields(result).get(0).value));assertEquals(400,HeaderCommands.fields(result).size());System.out.println("DL24_PIN400_MS "+(System.nanoTime()-s)/1000000);}
 @Test public void nestedIdentityProbesShareBoundedBudget()throws Exception{byte[] b=row("VLPLdeep");for(int n=0;n<25;n++){ByteArrayOutputStream o=new ByteArrayOutputStream();o.write(HeaderCommands.field(7,b));o.write(HeaderCommands.field(7,HeaderCommands.text("not-a-protobuf")));b=o.toByteArray();}int[] budget={LibraryPinOrder.WORK_NODES,2048};byte[] result=LibraryPinOrder.walk(b,new HashSet<String>(Arrays.asList("PLdeep")),0,budget);assertTrue(budget[0]<0);assertEquals("PLdeep",LibraryPinOrder.rowKey(row("VLPLdeep")));}
 @Test public void classMonitorCannotBlockUiTransform()throws Exception{Activity c=Robolectric.buildActivity(Activity.class).setup().get();ExecutorService worker=Executors.newSingleThreadExecutor();try{synchronized(LibraryPinOrder.class){Future<byte[]> f=worker.submit(()->LibraryPinOrder.reorder(row("VLPLnotcached"),c));assertNotNull(f.get(3,TimeUnit.SECONDS));}}finally{worker.shutdownNow();}}
}
